(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0351","batch":"08","category":"Categoria B","question":"Care dintre autoturisme s-a încadrat corect pentru a schimba direcția de mers?","answers":["Autoturismul roșu","Autoturismul albastru","Ambele autoturisme"],"correctIndices":[1],"correct":1,"explanation":"Atunci când în intersecție circulă și tramvaie, iar spațiul dintre șina din dreapta și trotuar nu permite circulația pe două sau mai multe rânduri, toți conducătorii de vehicule, indiferent de direcția pe care aceștia doresc să meargă, inclusiv cei ce doresc să vireze la stânga în intersecție, vor circula doar pe un singur rând, lăsând astfel liber traseul tramvaiului. În această situație autoturismul roșu nu s-a încadrat corect deoarece se află pe calea tramvaiului, nelăsând liber traseul acestuia. Autoturismul albastru s-a încadrat corespunzător pentru schimbarea direcției de mers către stânga. Mai mult de atât, în imaginea întrebării se observă că autoturismul roșu a intrat parțial pe sensul opus, lucru care este interzis.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0351.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0351.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 351; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată în care vehiculul roșu virează la stânga, iar vehiculul albastru virează la stânga. Se află pe același drum. Autoturismul roșu se află pe linia de tramvai. Autoturismul albastru se află pe o bandă normală. Linia de tramvai este separată de trotuar pe partea dreaptă de o singură bandă. Linia de tramvai prezintă șină în partea dreaptă.","needsImageReview":true,"source":"RoDrive · ID 350 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autoturisme-s-a-incadrat-corect-pentru-a-schimba-directia-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"350","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_360.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0352","batch":"08","category":"Categoria B","question":"Câte corpuri de iluminat are semaforul care se adresează pietonilor și bicicliștilor?","answers":["Două corpuri","Trei corpuri","Patru corpuri"],"correctIndices":[0],"correct":0,"explanation":"Semafoarele care se adresează pietonilor și bicicliștilor sunt formate din două corpuri, culorile acestora sunt: Când semnalul de culoare verde începe să funcționeze intermitent înseamnă că timpul afectat traversării drumului este în curs de epuizare și urmează semnalul roșu. În acest caz pietonul surprins în traversarea drumului trebuie să grăbească trecerea, iar dacă drumul este prevăzut cu un refugiu sau spațiu interzis circulației vehiculelor, să aștepte pe acesta apariția semnalului de culoare verde. Semnalul de culoare verde intermitent și semnalul de culoare roșie interzic pietonilor să se angajeze în traversare pe partea carosabilă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0352.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0352.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 352; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 351 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cate-corpuri-de-iluminat-are-semaforul-care-se-adreseaza-pietonilor-si-biciclistilor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"351","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0353","batch":"08","category":"Categoria B","question":"Căile respiratorii pot fi deblocate:","answers":["Numai în unități medicale, folosindu-se instrumente speciale","La locul accidentului, prin intervenții specifice","Indiferent unde, dacă victima suportă această intervenție"],"correctIndices":[1],"correct":1,"explanation":"În caz de accident, victima poate avea căile respiratorii (nas și gură) astupate, acestea trebuie eliberate ca victima să poată respira, procedura de deblocare a căilor respiratorii se face la locul accidentului, cât mai repede posibil, numai prin intervenții specifice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0353.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0353.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 353; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 352 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/caile-respiratorii-pot-fi-deblocate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"352","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0354","batch":"08","category":"Categoria B","question":"Sunteți obligat să opriți la semnalele date de:","answers":["Îndrumătorii de circulație ai ministerului apărării","Conducătorii vehiculelor de ambulanța","Inspectorii primăriei"],"correctIndices":[0],"correct":0,"explanation":"Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească și la semnalele îndrumătorilor de circulație ai Ministerului Apărării. Aceștia din urmă pot efectua, pe lângă semnalele de oprire, și următoarele semnale: balansarea brațului în plan vertical, cu palma mâinii orientată către sol sau cu un mijloc de semnalizare, care semnifică reducerea vitezei, precum și rotirea vioaie a brațului, care semnifică mărirea vitezei de deplasare a vehiculelor, inclusiv grăbirea traversării drumului de către pietoni. Nerespectarea semnalelor acestora se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni. Nu este obligatorie oprirea la semnalele date de conducătorii vehiculelor de ambulanță sau ale inspectorilor primăriei. În cazul conducătorilor vehiculelor de ambulanță, această întrebare nu se referă la semnalele speciale de avertizare cu lumină de culoare albastră și sonore, cu care sunt dotate vehiculele aparținând serviciului de ambulanță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0354.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0354.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 354; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 353 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-opriti-la-semnalele-date-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"353","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0355","batch":"08","category":"Categoria B","question":"Ce deprindere greșită a conducătorului auto determină frecvent defectarea ambreiajului?","answers":["Coborârea pantelor cu motorul oprit sau aducerea schimbătorului de viteze în punctul mort","Rularea cu jocuri mari la pedala de ambreiaj sau la mecanismul de direcție","Așteptarea la semafor având pedala de ambreiaj apăsată"],"correctIndices":[2],"correct":2,"explanation":"Este interzis prin regulament coborârea pantelor cu motorul oprit sau aducerea schimbătorului de viteze în punctul mort. În schimb, se recomandă ca la coborârea pantelor să se utilizeze frâna de motor, adică introducerea schimbătorului de viteze într-o treaptă de viteză, de regulă, inferioară treptei necesare în momentul respectiv. Astfel nu veți suprasolicita frâna de serviciu (frâna de picior). Utilizarea îndelungată a frânei de serviciu duce la supraîncălzirea discurilor si a plăcuțelor de frână, fapt care conduce și la încălzirea excesivă a lichidului de frână. Dacă lichidul de frână ajunge la punctul de fierbere, vor apărea bule de aer în lichid și forța de frânare va scădea foarte mult. Rularea cu jocuri mari la pedala de ambreiaj ne sugerează că defecțiunea deja a apărut, iar cauza poate fi chiar așteptarea la semafor având pedala de ambreiaj apăsată. Rularea cu jocuri mari la mecanismul de direcție este interzisă prin regulament. Dacă se ține apăsată pedala de ambreiaj atunci când nu este necesar, arcurile de presiune care împing placa de presiune pe discul de ambreiaj vor fi menținute în tensiune inutil în acea perioadă de timp. În timp, aceasta duce la slăbirea arcurilor de compresie și ambreiajul va începe să patineze, adică se va defecta. Prin urmare, deprinderea greșită a conducătorului auto, care determină defectarea frecventă a ambreiajului, este sprijinirea piciorului pe pedala de ambreiaj în timpul deplasării autovehiculului sau așteptarea la semafor având pedala de ambreiaj apăsată.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0355.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0355.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 355; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 354 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-deprindere-gresita-a-conducatorului-auto-determina-frecvent-defectarea-ambreiajului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"354","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0356","batch":"08","category":"Categoria B","question":"Conduita ecologică în conducerea unui autovehicul înseamnă:","answers":["Să nu poluați fonic mediul înconjurător, folosind sistemul de sonorizare la putere maximă","Să întrețineți în permanență autovehiculul curat, prin spălare și degresare zilnică","Să fiți calm și să anticipați situațiile astfel încât să evitați accelerarea și frânarea bruscă"],"correctIndices":[2],"correct":2,"explanation":"Poluarea fonică nu ține de conduita ecologică, neexistând nici un reziduu toxic rezultat în urma ei. Trebuie să reținem că este interzis conducătorului de autovehicul să folosească instalații de sonorizare la un nivel de zgomot care ar afecta deplasarea în siguranță a lui și a celorlalți participanți la trafic. La spălare și degresare se folosesc multe substanțe dăunătoare mediului care ajung în circuitul apei în natură. Prin urmare folosirea lor excesivă mărește poluarea, nu o combate. Conducerea agresivă, plecările în trombă și bruscarea frânelor măresc consumul de carburant cu până la 40%, prin urmare accelerarea puternică fără rost, pentru ca apoi să frânați brusc, în loc să aveți un parcurs cât mai cursiv, mărește cantitatea de noxe emisa de autovehicul, cauzând astfel un grad mai mare de poluare. Așadar conduita ecologică presupune să fiți calm și să anticipați situațiile pentru a nu fi obligat să accelerați sau să frânați brusc.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0356.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0356.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 356; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 355 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conduita-ecologica-in-conducerea-unui-autovehicul-inseamna","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"355","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0357","batch":"08","category":"Categoria B","question":"Unde se întâlnește acest indicator?","answers":["În zonele de deal și de munte","La începutul sectoarelor de drum acoperite de zăpadă, gheață sau polei","Pe toate drumurile lunecoase"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul se numește „Lanțuri pentru zăpadă”, acest indicator se întâlnește la capetele sectoarelor de drum cu declivități pronunțate sau curbe strânse pe care, atunci când partea carosabilă este acoperită cu zăpadă, gheață sau polei, este obligatoriu ca vehiculele să fie echipate cu lanțuri antiderapante pe cel puțin două roți motoare. Obligația este valabilă indiferent de masa maxima totală autorizată a vehiculului. Indicatorul „Lanțuri pentru zăpadă” este însoțit de panoul adițional „Polei, gheață, zăpadă”. Acesta poate fi însoțit și de panoul adițional „Categoria de autovehicule la care se referă indicatorul” pentru a preciza pentru care categorie de autovehicule este obligatorie semnificația indicatorului. Trebuie să ținem cont că legislația rutieră, prin Articolul 148, pct. 14 din Regulament, obligă conducătorii autovehiculelor cu o masă totală maximă autorizatămai mare de 3,5 tonesă echipeze aceste autovehicule cu anvelope de iarnă pe roțile axei/axelor de tracțiune sau, în lipsa anvelopelor de iarnă, cu lanțuri ori alte echipamente antiderapante certificate. Este important să reținem că acest articol de lege lasă,la alegere, două variante, fieanvelope de iarnă pe roțile axei/axelor de tracțiune, fielanțuri ori alte echipamente antiderapante certificate aplicate pe anvelopele de vară. Însă indicatorul „Lanțuri pentru zăpadă” nu lasă nicio opțiunie, acesta obligă la dotarea cu lanțuri pentru zăpadă, indiferent dacă anvelopele sunt de vară sau de iarnă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0357.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0357.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 357; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator albastru, circular, ce conține un cauciuc care prezintă lanțuri. Indicatorul este adesea întâlnit înaintea drumurilor cu zăpadă.","needsImageReview":true,"source":"RoDrive · ID 356 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/unde-se-intalneste-acest-indicator","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"356","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_367.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0358","batch":"08","category":"Categoria B","question":"Ce autovehicul își poate continua deplasarea în imaginea prezentată?","answers":["Autocamionul","Autoturismul verde","Autoturismul roșu"],"correctIndices":[2],"correct":2,"explanation":"Intersecția este dirijată cu semnale luminoase, toate autovehiculele s-au încadrat corect și trebuie să respecte semnificația semnalelor luminoase ale semafoarelor. În această situație întâlnim două semafoare cu semnale de culori diferite. Însă sub fiecare semafor se găsește instalat câte un panou adițional, în acest caz semnalul semaforului va fi respectat de cei a căror direcție de deplasare se regăsește pe aceste panouri adiționale. Mai mult de atât, trebuie să ținem cont și de marcajele cu săgeți aplicate pe fiecare bandă de circulație, acestea obligă la respectarea direcției sau direcțiilor indicate prin acele săgeți. De exemplu, dacă pe banda pe care te afli se găsește marcajul care obligă la circulația doar pe direcția înainte, trebuie să urmezi doar această direcție, dar ținând cont de culoarea semaforului pentru acea direcție. În situația expusă în imaginea întrebării toate cele trei autovehicule s-au încadrat corect pentru direcțiile de mers dorite. Prin urmare, autoturismul verde dorește să vireze la dreapta și va trebui să respecte semnificația semnalului semaforului din partea dreaptă,deci NU își poate continua deplasarea. Autocamionul dorește să circule pe direcția înainte și trebuie să respecte semnificația semnalului semaforului din partea dreaptă,deci NU își poate continua deplasarea. Autoturismul roșu dorește să vireze la stânga și va trebui să respecte semnalul semaforului din partea stângă,deci își poate continua deplasarea. Așadar, singurul care își poate continua deplasarea în cazul de față este autoturismul roșu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0358.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0358.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 358; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată în care vehiculele au semnale diferite. Vehiculul roșu are semafor verde, aflându-se pe marcaj rutier care îi obligă virajul la stânga, iar vehiculul verde are semafor roșu, aflându-se pe marcaj care îi permite deplasarea înainte sau la dreapta. Camionul albastru are semafor roșu și se află pe marcaj care îi permite deplasarea înainte.","needsImageReview":true,"source":"RoDrive · ID 357 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-autovehicul-isi-poate-continua-deplasarea-in-imaginea-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"357","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_368.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0359","batch":"08","category":"Categoria B","question":"Ce vehicule aveți permisiunea de a depăși în situația dată?","answers":["Vehiculele cu tracțiune animală, bicicletele și motocicletele fără ataș","Autoturismele, motocicletele fără ataș și vehiculele cu tracțiune animală","Autovehiculele, cu excepția motocicletelor fără ataș"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă”. La întâlnirea acestui indicator depășirea autovehiculelor, cu excepția motocicletelor fără ataș, este interzisă. Prin urmare, la întâlnirea acestui indicator, puteți depăși motociclete fără ataș, mopede și vehicule simple (biciclete, vehicule cu tracțiune animală, vehicule împinse sau trase cu brațul, etc.). Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie continuă, iarpentru depășirea acestor vehicule este obligatorie încălcarea sau trecerea peste acest marcaj. Singura opțiune, regulamentară, este de a merge în spatele acestor vehicule pân","imageUrl":"/nivel-1/quiz-images/rodrive-all/0359.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0359.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 359; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu marcaj transversal longitudinal continuu și indicatorul circular cu margini roșii, ce prezintă la dreapta o mașină roșie iar la dreapta una neagră, ce interzice depășirea, cu excepția depășirii motocicletelor fără ataș.","needsImageReview":true,"source":"RoDrive · ID 358 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-vehicule-aveti-permisiunea-de-a-depasi-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"358","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_369.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0360","batch":"08","category":"Categoria B","question":"Ce se înțelege prin distanța de cel puțin 50 m de la care conducătorul de autovehicul este obligat să semnalizeze intenția de a depăși în localitate?","answers":["Distanța dintre autovehiculul care depășește și cel care urmează să fie depășit","Distanța dintre locul în care s-a semnalizat intenția de a depăși și locul în care se schimbă poziția de mers a autovehiculelor pentru începerea depășirii","Distanța dintre autovehiculul angajat în depășire și locul unde efectuează depășirea"],"correctIndices":[1],"correct":1,"explanation":"Intenția conducătorilor de autovehicule de a efectua manevra de depășire se semnalizează prin punerea în funcțiune a luminilor indicatoare de direcție cu cel puțin 50 de metri în localități și 100 de metri în afara localităților, înainte de începerea efectuării manevrei. Distanța de cel puțin 50 de metri în localități semnifică distanța dintre locul în care semnalizăm intenția de a efectua manevra și locul în care se începe manevra, adică distanța parcursă cu semnalizatorul în funcțiune până când începeți efectuarea manevrei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0360.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0360.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 360; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 359 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-intelege-prin-distanta-de-cel-putin-50-m-de-la-care-conducatorul-de-autovehicul-este-obligat-sa-semnalizeze-intentia-de-a-depasi-in-lo","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"359","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0361","batch":"08","category":"Categoria B","question":"Care dintre indicatoare obligă la schimbarea direcției de mers pe prima stradă la dreapta?","answers":["Indicatorul 1","Indicatorul 2","Ambele indicatoare"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul 1 se numește “Ocolire”. Acesta se amplasează înaintea unui obstacol aflat pe partea carosabilă și vă obligă să ocoliți obstacolul prin partea dreaptă. Sensul săgeții poate indica, după caz, la stânga. Indicatorul 2 se numește “La dreapta” și vă obligă să virați către dreapta în intersecția înaintea căreia se află instalat, manevra executându-se după depășirea indicatorului. Având în vedere că între a ocoli un obstacol prin dreapta și a executa un viraj la dreapta este diferență, doar indicatorul 2 “La dreapta” obligă la schimbarea direcției de mers pe prima stradă la dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0361.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0361.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 361; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă două indicatoare: (1) Indicator circular albastru cu săgeată albă cu direcția spre dreapta-jos, ce obligă ocolirea prin dreapta și (2) Indicator circular albastru cu linie curbă spre dreapta albă, ce semnifică viraj obligatoriu la dreapta.","needsImageReview":true,"source":"RoDrive · ID 360 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-indicatoare-obliga-la-schimbarea-directiei-de-mers-pe-prima-strada-la-dreapta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"360","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_371.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0362","batch":"08","category":"Categoria B","question":"Care sunt vehiculele care au prioritate de trecere într-o intersecție dirijată?","answers":["Autocamioanele de mare tonaj","Vehiculele aparținând protecției civile, semnalizate ca atare","Vehiculele aparținând serviciului de ambulanță, când au în funcțiune semnalele speciale luminoase și sonore"],"correctIndices":[2],"correct":2,"explanation":"Autocamioanele de mare tonaj nu beneficiază de prioritate de trecere specială. Vehiculele aparținând Protecției Civile au prioritateDOARatunci când au în funcțiune semnalele speciale de avertizare luminoase și sonore. Trebuie știut că acestea trebuie să aibă ambele tipuri de semnalizare (luminoasă și sonoră) în funcțiune pentru a beneficia de regimul de circulație prioritar. În toate tipurile de intersecție, prioritate de trecere vor avea autovehiculele cu regim de circulație prioritar, atunci când se deplasează în acțiuni de intervenție sau în misiuni care au caracter de urgență și au în funcțiune semnalele de avertizare speciale luminoase și sonore. Trebuie știut că acestea trebuie să aibă ambele tipuri de semnalizare (luminoasă și sonoră) în funcțiune pentru a beneficia de regimul de circulație prioritar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0362.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0362.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 362; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 361 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-sunt-vehiculele-care-au-prioritate-de-trecere-intr-o-intersectie-dirijata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"361","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0363","batch":"08","category":"Categoria B","question":"Distrugerea, degradarea sau aducerea în stare de neîntrebuințare, în mod intenționat, a indicatoarelor, semafoarelor, amenajărilor rutiere se pedepsește astfel:","answers":["Cu amendă contravențională și puncte de penalizare","Penal","Cu suspendarea exercitării dreptului de a conduce autovehicule"],"correctIndices":[1],"correct":1,"explanation":"Distrugerea, degradarea sau aducerea în stare de neîntrebuințare a unui bun aparținând altuia, prin urmare și distrugerea, degradarea sau aducerea în stare de neîntrebuințare, în mod intenționat, a indicatoarelor, semafoarelor, amenajărilor rutiere se pedepsește penal. În legislația rutieră veche (OUG 195/2002) exista un articol care reglementa fix aceste fapte care se regăsesc în enunțul întrebării. Acel articol a fost eliminat (abrogat) la 01-02-2014, însă faptele enumerate în enunțul întrebării cad acum sub incidența articolului 253 alineatul 1 din Codul Penal (actualizat).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0363.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0363.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 363; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 362 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/distrugerea-degradarea-sau-aducerea-in-stare-de-neintrebuintare-in-mod-intentionat-a-indicatoarelor-semafoarelor-amenajarilor-rutiere-se-ped","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"362","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0364","batch":"08","category":"Categoria B","question":"Indicatorul semnifică:","answers":["„viteză minimă obligatorie“","„sfârșitul limitării de viteză“","„sfârșitul vitezei minime obligatorii“"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul se numește “Sfârșitul vitezei minime obligatorii”, acest indicator anunță terminarea sectorului de drum pe care a fost impusă o viteză minimă obligatorie de 40 km/h, la începutul sectorului de drum cu viteză minimă obligatorie se instalează indicatorul “Viteza minimă obligatorie”. Trebuie știut că în cazul în care pe sectorul de drum pe care viteza minimă a fost reglementată prin indicator sau prin alte mijloace, se circulă cu o viteză mai mică cu cel puţin 10 km/h sub limita minimă obligatorie stabilită, fără motiv, se sancționează contravențional cu amendă prevăzută în clasa I de sancţiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0364.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0364.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 364; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular albastru, cu inscripția albă 40 și o linie roșie oblică arată sfârșitul limitei de viteză de 40 km/h.","needsImageReview":true,"source":"RoDrive · ID 363 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"363","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_374.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0365","batch":"08","category":"Categoria B","question":"În situația dată:","answers":["Veți circula cu prudență până la prima intersecție","Veți circula cu maximum 30 km/h pe sectorul de drum denivelat","Veți circula cu minimum 30 km/h"],"correctIndices":[1],"correct":1,"explanation":"În situația dată circulați pe un drum cu denivelări semnalizat corespunzător, indicatorul de avertizare cu formă triunghiulară se numește “Drum cu denivelări”. La întâlnirea acestui indicator conducătorii auto sunt obligați să reducă viteza de deplasare până la maxim 30 de km/h în localități și 50 de km/h în afara localităților. Prin urmare, fie că sub acest indicator “Drum cu denivelări” este sau nu instalat indicatorul de limitare de viteză, aveți obligația de a reduce viteza de deplasare până la maxim 30 de km/h în localități și 50 de km/h în afara localităților. Însă și indicatorul “Limitare de viteză” instalat sub cel de avertizare limitează viteza de deplasare la maxim 30 km/h, fiind instalat pentru a atrage atenția la faptul că trebuie să reduceți viteza de deplasare la maxim 30 de km/h. Dar pentru că este instalat lângă cel de avertizare, zona de acțiune se termină odată cu terminarea sectorului de drum cu denivelări. Deci în situația dată aveți obligația de a vă deplasa cu o viteză maximă de 30 km/h pe sectorul de drum cu denivelări.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0365.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0365.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 365; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție din perspectiva unui șofer cu indicatorul triunghiular cu margini roșii cu un drum negru, denivelat, ce semnifică drum denivelat și un indicator circular cu margini roșii și inscripția neagră 30, de limitare a vitezei la 30 km/h.","needsImageReview":true,"source":"RoDrive · ID 364 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"364","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_375.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0366","batch":"08","category":"Categoria B","question":"Cum trebuie să procedați atunci când intrați, pe timp de zi, într-un tunel iluminat necorespunzător?","answers":["Claxonați","Aprindeţi luminile de întâlnire","Aprindeţi lumina intermitentă de avertizare"],"correctIndices":[1],"correct":1,"explanation":"Indiferent dacă tunelul este sau nu iluminat corespunzător, la intrarea în acestaNUeste necesar să claxonați. Acest lucru nu vi se interzice, însă nici nu ajută în acest caz. Mijloacele de avertizare sonoră se folosesc pentru evitarea unui pericol imediat. Atunci când intrați într-un tunel sunteți obligat să aprindeți luminile de întâlnire, indiferent dacă acesta este sau nu iluminat corespunzător și indiferent dacă circulați pe timp de zi sau de noapte. Deși legislația rutieră a fost actualizată iar în acest moment este obligatoriu ca la circulațiape timpul zilei, pe toate categoriile de drum public, să se circule având în funcțiune luminile de întâlnire (faza scurtă)sauluminile pentru circulația diurnă (DRL), răspunsul la această întrebare rămâne în continuare corect și conform cu legislația. Pentru a înțelege mai bine această regulă dăm următorul exemplu: Un conducător de autovehicul circulă pe timpul zilei,în condiții normale, caz în care are obligația de a pune în funcțiunefie luminile de întâlnire(adică faza scurtă),fie luminile pentru circulația diurnă(DRL), după cum consideră acesta, ori poate chiar să le folosească pe ambele în același timp. Însă dacă acesta circulă printr-un tunel, opțiunea de a alege să pună în funcțiune luminile pentru circulația diurnă (DRL)în locul luminilor de întâlnire(faza scurtă)NUmai este valabilă pentru că legislația rutieră prevede că în acest cazeste obligatoriu să se folosească luminile de întâlnire(faza scurtă), fără a mai lăsa opțiunea de a se folosi luminile pentru circulația diurnă (DRL) în schimbul luminilor de întâlnire. Mai mul","imageUrl":"/nivel-1/quiz-images/rodrive-all/0366.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0366.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 366; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 365 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-atunci-cand-intrati-pe-timp-de-zi-intr-un-tunel-iluminat-necorespunzator","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"365","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0367","batch":"08","category":"Categoria B","question":"Staționarea este interzisă:","answers":["În zona de acțiune a indicatorului „circulație în ambele sensuri“","Pe sectoarele de drum unde este interzisă depășirea prin indicator","Pe partea carosabilă a drumurilor naționale"],"correctIndices":[1],"correct":1,"explanation":"Nu se interzice staționarea în zona de acțiune a indicatorului „Circulație în ambele sensuri”. Acest indicator are rolul de a atenționa conducătorul auto că pe sectorul de drum următor se va circula în ambele sensuri. Se interzice staționarea voluntară a vehiculelor în toate locurile și situațiile unde depășirea vehiculelor este interzisă. De exemplu la întâlnirea indicatorului „Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă” se interzice staționarea deoarece îi obligă pe ceilalți participanți la trafic sa efectueze manevra de depășire, manevră care este interzisă pe acel sector de drum. Nu se interzice staționarea nici pe partea carosabilă a drumurilor naționale. Staționarea voluntară a vehiculelor se interzice pe partea carosabila a drumurilor naționale europene (E). Drumurile Naționale sunt diferite de drumurile Naționale Europene (E).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0367.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0367.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 367; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 366 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/stationarea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"366","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0368","batch":"08","category":"Categoria B","question":"Este corectă manevra de devansare pe autostradă a unui autovehicul pe banda dreaptă a acestuia?","answers":["Da","Nu","Da, dar numai dacă se folosesc semnalele de atenționare sonore și luminoase"],"correctIndices":[0],"correct":0,"explanation":"Depășirea vehiculelorpe partea dreaptă a acestora este interzisă, însă în situația în care un vehicul circulă mai repede pe una dintre benzi decât vehiculele care circulă pe altă bandă, în același sens de circulație, nu se consideră depășire. Aceasta se consideră devansare iar manevra este regulamentară, indiferent pe ce parte se face devansarea. Pe drumurilecu o singură bandă de circulație pe sensnu se poate efectua manevra de devansare, caz în care manevra se numește depășire și se poate efectua doar pe partea stângă a vehiculului depășit. Devansarea este posibilă doar pe drumurile publice cu cel puțin două benzi de circulație pe sens. În această întrebare este vorba despre o autostradă, iar autostrada are cel puțin două benzi de circulație pe sens.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0368.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0368.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 368; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 367 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-corecta-manevra-de-devansare-pe-autostrada-a-unui-autovehicul-pe-banda-dreapta-a-acestuia","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"367","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0369","batch":"08","category":"Categoria B","question":"Cum veți proceda noaptea, când vizibilitatea este redusă din cauza ceții, din punct de vedere al circulației preventive?","answers":["Circulați cât mai aproape de axul drumului","Circulați cât mai aproape de marginea din dreapta a drumului public","Păstrați o distanță egală între axa drumului și marginea din dreapta a părții carosabile, rulând cu o viteză care să asigure oprirea într-un spațiu mai mic decât cel de vizibilitate"],"correctIndices":[2],"correct":2,"explanation":"Atunci când vizibilitatea este redusă din cauza ceții, pe timp de noapte, dacă circulați cât mai aproape de axul drumului sau cât mai aproape de marginea din dreapta a drumului public, este posibil ca vehiculele care vin din sens opus sa nu vă poată observa în timp util pentru a evita un eventual impact, sau vehiculele staționate pe partea dreaptă a drumului vă pot surprinde cu prezența lor din cauza vizibilității reduse. Atunci când vizibilitatea este redusă din cauza ceții dense, indiferent că circulați pe timp de zi sau de noapte, trebuie să păstrați o distanță egală între axa drumului și marginea din dreapta a părții carosabile și să vă deplasați cu o viteză care să asigure oprirea într-un spațiu mai mic decât cel de vizibilitate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0369.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0369.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 369; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 368 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-noaptea-cand-vizibilitatea-este-redusa-din-cauza-cetii-din-punct-de-vedere-al-circulatiei-preventive","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"368","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0370","batch":"08","category":"Categoria B","question":"Semnalul polițistului indică:","answers":["Circulația pe direcția înainte nu este posibilă","Oprire","Circulația prin intersecție se va face cu viteză redusă"],"correctIndices":[1],"correct":1,"explanation":"Brațele polițistului rutier întinse orizontal semnifică oprire pentru toți participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațele acestuia, mai exact pentru cei care vin din fața și din spatele polițistului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0370.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0370.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 370; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un polițist rutier cu brațele întinse lateral. Acest semnal indică oprirea obligatorie pentru vehiculele care vin din fața și din spatele polițistului.","needsImageReview":true,"source":"RoDrive · ID 369 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-politistului-indica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"369","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_380.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0371","batch":"08","category":"Categoria B","question":"Care dintre cele trei vehicule va trece ultimul prin intersecție?","answers":["Autobuzul","Autoturismul","Autocamioneta mov"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este dirijată cu indicatoare de reglementare de prioritate, pe drumul cu prioritate circulă autobuzul, acesta va trece primul prin intersecție. Între autoturism și autocamioneta mov s-a creat o situație de egalitate deoarece ambele vehicule întâlnesc indicatorul cedează trecerea, situație în care se va aplica regula priorității de dreapta, autoturismul fiind obligat să îi acorde prioritate de trecere autocamionetei mov deoarece aceasta îi vine din partea dreaptă. Ordinea de trecere este următoarea: autobuzul, urmat de autocamioneta mov, iar ultimul prin intersecție va trece autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0371.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0371.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 371; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată văzută de sus. Camionul din stânga vrea să vireze la stânga, autobuzul din dreapta vrea să vireze la dreapta, iar autoturismul de sus vrea să circule înainte. Toate drumurile au indicatoare fie triunghiulare cu margini roșii, fie indicatoare romboidale cu fundal galben și margini albe însoțite de panouri adiționale, care arată faptul că drumul din dreapta care continuă cu viraj la dreapta este prioritar.","needsImageReview":true,"source":"RoDrive · ID 370 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-trei-vehicule-va-trece-ultimul-prin-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"370","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_381.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0372","batch":"08","category":"Categoria B","question":"În care dintre situații depășirea este interzisă?","answers":["În intersecțiile cu circulație nedirijată și la trecerile pentru pietoni semnalizate","În intersecții și la o distanță de 50 m de acestea","În zona de acțiune a indicatorului „limitare de viteză“"],"correctIndices":[0],"correct":0,"explanation":"Regulamentul rutier interzice depășirea vehiculelor în anumite locuri și situații, printre care se numără și următoarele: La o distanță de 50 metri de intersecțieeste permisă manevra de depășire, indiferent dacă intersecția este sau nu dirijată, cu condiția ca semnalizarea rutieră din acel loc să nu dispună altfel. Această manevră se interzice înintersecțiile cu circulațienedirijatășinu se specifică și o anumită distanță față de intersecție de unde începe interzicerea acestei manevre. Prin urmare, varianta B de răspuns nu poate fi considerată corectă. A nu se confunda manevra de depășire cu manevra de oprire. Manevra de oprire este interzisă în intersecții, inclusiv în cele cu circulație în sens giratoriu, precum și în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora, la o distanță mai mica de 25 de metri de coltul intersecției. În zona de acțiune a indicatorului „Limitare de viteză“nu se interzice manevra de depășire. Se poate efectua manevra de depășire, dar cu condițiasă nu se depășească viteza maximă impusăde respectivul indicatorul de limitare de viteză.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0372.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0372.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 372; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 371 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-depasirea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"371","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0373","batch":"08","category":"Categoria B","question":"În această situație opriți:","answers":["La linia transversală","În dreptul semaforului","Pe trecerea pentru pietoni"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți semnalul roșu al semaforului, semnal care interzice trecerea. La semnalul de culoare roșie vehiculul trebuie oprit înaintea marcajului pentru oprire sau, după caz, înaintea marcajului pentru trecerea pietonilor, iar în lipsa acestuia, în dreptul semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0373.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0373.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 373; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată unde semaforul este roșu. În fața sa, se află o trecere de pietoni și o linie transversală, mai apropiată de șofer.","needsImageReview":true,"source":"RoDrive · ID 372 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-opriti","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"372","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_383.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0374","batch":"08","category":"Categoria B","question":"În care dintre următoarele situații vă este interzis să măriți viteza de deplasare?","answers":["Când urmează să fiți depășit","La sesizarea aparaturii de detectare a sistemelor radar","Pe timp de noapte"],"correctIndices":[0],"correct":0,"explanation":"Atunci când urmează să fiți depășit aveți obligația de a nu mări viteza de deplasare și de a circula cât mai aproape de marginea din dreapta a părții carosabile sau a benzii pe care vă deplasați. Aparatura de detectare a sistemelor radar este acel dispozitiv (detector radar) folosit de conducătorii de autovehicule pentru a-i anunța dacă în apropiere se află un aparat radar. Atenție, întredetectorul de radarșianti-radareste o diferență mare.Detectorul de radareste permis de lege și doar vă avertizează despre prezența aparatelor radar.Anti-radarul NUeste permis de lege, este acel aparat care bruiază semnalul emis de aparatul radar al poliției pentru ca aceștia sa nu vă poată intercepta viteza cu care vă deplasați. Prin urmare, aparatura de detectare a sistemelor radar o folosiți chiar dvs. și este lipsit de logică să vă fie interzis să măriți viteza de deplasare la sesizarea acestei aparaturi. Pe timpul nopții, nu vă este interzis să măriți viteza de deplasare, atât timp cât nu depășiți viteza maximă admisă pe sectorul de drum respectiv pentru categoria din care face parte autovehiculul condus. Dar trebuie reținut că pe timpul nopții, atunci când întâlniți un alt vehicul care circulă din sens opus, trebuie să folosiți luminile de întâlnire de la o distanță de cel puțin 200 de metri și să reduceți viteza de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0374.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0374.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 374; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 373 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-urmatoarele-situatii-va-este-interzis-sa-mariti-viteza-de-deplasare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"373","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0375","batch":"08","category":"Categoria B","question":"Care este regula priorității de trecere la intersecția a două drumuri de aceeași categorie, cu circulație nedirijată?","answers":["Prioritatea de dreapta","Prioritatea primului sosit","Prioritatea de drum principal"],"correctIndices":[0],"correct":0,"explanation":"La intersecția nedirijată a două drumuride aceeași categorie, ca de exemplu o intersecție de două drumuri comunale sau două străzi dintr-un oraș, se va aplica regula priorității de dreapta, astfel vehiculul care vine din partea dreaptă are prioritate. Trebuie să reținem că regula priorității de dreapta se aplică doar in intersecțiile nedirijate de drumuride aceeași categorie. Dacă intersecția nedirijată este de drumuri de categorii diferite, ca de exemplu un drum județean și un drum comunal, prioritatea de trecere se va acorda în felul următor:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0375.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0375.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 375; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 374 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-regula-prioritatii-de-trecere-la-intersectia-a-doua-drumuri-de-aceeasi-categorie-cu-circulatie-nedirijata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"374","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0376","batch":"08","category":"Categoria B","question":"Căror categorii de autovehicule le este interzis să circule pe autostradă?","answers":["Celor care, prin construcție, nu pot depăși viteza de 50 km/oră","Motocicletelor cu și fără ataș","Tractoarelor și mașinilor agricole autopropulsate"],"correctIndices":[0,2],"correct":0,"explanation":"Pe autostradă este interzisă circulația tractoarelor, a mașinilor autopropulsate pentru lucrări agricole și a vehiculelor care, prin construcție sau din alte cauze, nu pot depăși viteza de 50 de km/h. Motocicletelor, cu sau fără ataș, le este permis să circule pe autostradă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0376.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0376.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 376; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 375 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/caror-categorii-de-autovehicule-le-este-interzis-sa-circule-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"375","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0377","batch":"08","category":"Categoria B","question":"Cum procedați în situația în care, după resuscitarea cardio-respiratorie, accidentatul își recapătă pulsul?","answers":["Încetați compresiile exterioare ale pieptului","Continuați compresiile exterioare ale pieptului","Aplicați un bandaj toracic"],"correctIndices":[0],"correct":0,"explanation":"Dacă în timpul sau după efectuarea resuscitării cardio-respiratorie a unei victime, observați că aceasta își recapătă pulsul, trebuie să încetați compresiile exterioare ale pieptului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0377.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0377.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 377; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 376 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-in-care-dupa-resuscitarea-cardio-respiratorie-accidentatul-isi-recapata-pulsul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"376","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0378","batch":"08","category":"Categoria B","question":"Ce semnifică indicatorul?","answers":["Sfârșitul zonei de staționare cu durată limitată","Limitare de viteză la 40 km/h","Sfârșitul zonei în care viteza este limitată la 40 km/h"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Sfârșitul limitării de viteză”. Acest indicator precizează sfârșitul sectorului de drum pe care s-a impus limitarea vitezei la maxim 40 km/h, limitare impusă prin indicatorul „Limitare de viteză”","imageUrl":"/nivel-1/quiz-images/rodrive-all/0378.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0378.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 378; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu indicatorul circular alb, inscripționat cu 40 și cu o linie oblică neagră, ce reprezintă sfârșitul zonei cu viteză limitată la 40km/h.","needsImageReview":true,"source":"RoDrive · ID 377 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-indicatorul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"377","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_388.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0379","batch":"08","category":"Categoria B","question":"În ce ordine vor trece prin intersecție cele trei autoturisme?","answers":["Roșu, albastru, verde","Verde, roșu, albastru","Albastru, roșu, verde"],"correctIndices":[1],"correct":1,"explanation":"În intersecția din imagine circulația nu se desfășoară în sens giratoriu, circulația este dirijată prin indicatoare de reglementare de prioritate. Sub fiecare indicator se găsește instalat câte un panou adițional care ne indică direcția drumului cu prioritate. În acest caz, pe drumul cu prioritate circulă autoturismul verde, deci acesta va trece primul prin intersecție. Între autoturismul albastru și cel roșu s-a creat o situație de egalitate, ambele întâlnind indicatorul \"Cedează trecerea\", situație în care se va aplica regula priorității de dreapta. Autoturismul albastru îi va acorda prioritate de trecere autoturismului roșu, deoarece acesta îi vine din partea dreaptă. Deci autoturismul roșu trece al doilea prin intersecție, iar ultimul prin intersecție circulă autoturismul albastru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0379.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0379.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 379; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție cu sens giratoriu, văzută de sus, în care sunt implicate trei autoturisme: roșu, albastru, verde . Drumul este semnalizat cu indicatoare de 'Sens giratoriu' și 'Cedează trecerea' pentru vehiculele care intră din dreapta (mașina roșie) și de sus (mașina roșie). Mașina verde deja circulă în sensul giratoriu și semnalizează pentru a ieși, aflându-se pe drum prioritar. Mașina roșie dorește să meargă înainte, intrând și ieșind pe direcția opusă. Mașina albastră dorește să vireze la stânga, ieșind în stânga jos. Indicatorul romboidal galben cu margine albă de prioritate și panoul adițional de pe partea de jos (colț dreapta jos) arată că drumul cu prioritate urmează traseul prin sensul giratoriu dinspre dreapta jos spre stânga. Astfel, mașina verde circulă deja pe drumul prioritar. Mașinile roșie și albastră au indicatorul triunghiular cu margini roșii, 'Cedează trecerea' și panouri adiționale care semnifică acel drum prioritar față de care trebuie să cedeze trecerea.","needsImageReview":true,"source":"RoDrive · ID 378 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-prin-intersectie-cele-trei-autoturisme","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"378","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_389.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0380","batch":"08","category":"Categoria B","question":"În care dintre situații conducătorul de vehicule este obligat, pe timp de noapte, să schimbe lumina de drum cu cea de întâlnire?","answers":["Când drumul este neiluminat","Când circulă în localitate, pe un drum cu mai multe benzi pe sens","În cazul în care din sens opus se apropie un autovehicul, de la o distanță de cel puțin 200 m"],"correctIndices":[2],"correct":2,"explanation":"Legislația rutieră nu prevede ca atunci când, pe timp de noapte, drumul este neiluminat să schimbați lumina de drum (faza lungă) cu cea de întâlnire (faza scurtă). Legislația rutieră nu prevede ca atunci când circulați pe timp de noapte în localitate, pe un drum cu mai multe benzi pe sens, să schimbați lumina de drum (faza lungă) cu cea de întâlnire (faza scurtă) Pe timpul nopții, la apropierea de un alt vehicul care circulă din sens opus, sunteți obligat ca de la distanța de cel puțin 200 de metri să folosiți luminile de întâlnire (faza scurtă), concomitent cu reducerea vitezei. Astfel, dacă aveți în funcțiune lumina de drum (faza lungă), aveți obligația de a o schimba cu lumina de întâlnire (faza scurtă).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0380.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0380.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 380; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 379 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-conducatorul-de-vehicule-este-obligat-pe-timp-de-noapte-sa-schimbe-lumina-de-drum-cu-cea-de-intalnire","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"379","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0381","batch":"08","category":"Categoria B","question":"Vă apropiați de o trecere la nivel cu calea ferată curentă fără bariere, în traversarea căreia s-a angajat o căruță aflată în fața dvs. În această situație puteți efectua depășirea?","answers":["Da, dacă aceasta nu a ajuns încă la linia de tren","Da, întrucât căruța este un vehicul lent","Nu"],"correctIndices":[2],"correct":2,"explanation":"Este interzisă depășirea tuturor vehiculelor, chiar și a vehiculelor lente precum căruțele, pe trecerile la nivel cu calea ferată curentă și la mai puțin de 50 m înainte de acestea. Prin urmare, atunci când vă apropiați de o trecere la nivel cu calea ferată curentă fără bariere,în traversareacăreia s-a angajat o căruță aflată în fața dvs., însemnând că aceasta se aflăchiar pe trecerea la nivelsau la o distanță mai mică de 50 de metri,NUvă este permisă depășirea acesteia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0381.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0381.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 381; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 380 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-apropiati-de-o-trecere-la-nivel-cu-calea-ferata-curenta-fara-bariere-in-traversarea-careia-s-a-angajat-o-caruta-aflata-in-fata-dvs-in-ace","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"380","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0382","batch":"08","category":"Categoria B","question":"Indicatorul vă avertizează că:","answers":["Drumul se intersectează cu o trecere la nivel cu linii de tramvai","Urmează o stație de tramvai prevăzută cu refugiu pentru pietoni","Urmează o trecere la nivel cu o cale ferată fără bariere sau semibariere, cu semnalizare automată"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul din imagine se numește “Trecere la nivel cu linii de tramvai”, acest indicator avertizează conducătorii de vehicule că drumul pe care circulă se intersectează cu linii de tramvai, deci prin intersecția următoare vor circula și tramvaie. Acest indicator se amplasează chiar dacă linia de tramvai intersectează numai un sens sau numai o bandă de circulație. Tramvaiele sunt vehicule cu priorități speciale iar în cazul în care următoarea intersecțieeste nedirijatăva trebui să te conformezi acestor reguli speciale, acordând prioritate tramvaielor în mers (în intersecțiile nedirijate, tramvaiele în mers pierd proprietatea doar atunci când execută virajul spre stânga).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0382.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0382.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 382; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție aglomerată cu indicatorul triunghiular cu margini roșii ce conține un tramvai, ce semnalizează un drum intersectat cu linii de tramvai.","needsImageReview":true,"source":"RoDrive · ID 381 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-va-avertizeaza-ca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"381","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_392.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0383","batch":"08","category":"Categoria B","question":"Pe o porțiune de drum acoperită cu polei, sesizați impactul inevitabil cu un câine. Cum veți proceda pentru evitarea unui accident?","answers":["Considerați că o asemenea situație nu vi se poate întâmpla","Eliberați accelerația, mențineți ferm volanul pe direcția de deplasare, fiind pregătit pentru a stabiliza autovehiculul după impact, prin manevrarea lină a volanului","Încercați, pe cât posibil, să evitați impactul frontal, prin manevrarea bruscă a volanului în direcția de deplasare opusă câinelui"],"correctIndices":[1],"correct":1,"explanation":"Animalele sunt imprevizibile tot timpul, așadar nu este cazul să considerați că o asemenea situație nu vi se poate întâmpla. În întrebare se specifică faptul că vă aflațipe o porțiune de drum acoperită cu poleiși căimpactul esteinevitabil, caz în care manevrele de evitare vor fi fără efect. Atunci când circulați pe o porțiune de drum acoperită cu polei și sesizați impactul inevitabil cu un câine, pentru evitarea unui accident, trebuie să eliberați accelerația și să mențineți ferm volanul pe direcția de deplasare, fiind pregătit pentru a stabiliza autovehiculul după impact. Manevrarea bruscă a volanului în direcția de deplasare opusă câinelui, având în vedere că vă aflați pe o porțiune de drum acoperită cu polei, cel mai probabil va duce la pierderea totală a aderenței și la derapaj și urmările vor fi mult mai grave.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0383.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0383.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 383; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 382 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pe-o-portiune-de-drum-acoperita-cu-polei-sesizati-impactul-inevitabil-cu-un-caine-cum-veti-proceda-pentru-evitarea-unui-accident","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"382","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0384","batch":"08","category":"Categoria B","question":"În cazul unui accidentat care nu respiră, pulsul este verificat:","answers":["Sub mandibulă","Lângă ureche","Pe partea laterală a epiglotei (mărul lui adam), în scobitura dintre trahee și mușchii gâtului"],"correctIndices":[2],"correct":2,"explanation":"În cazul în care un accidentat nu respiră, va trebui să îi luați pulsul. Verificarea pulsului se face prin plasarea a două degete (arătătorul și mijlociul) pe partea laterală a gâtului, puțin deasupra mărului lui Adam, în spațiul dintre trahee și mușchii gâtului sau prin ascultarea bătăilor inimii, apropiind urechea de pieptul victimei. Dacă victima nu respiră dar are puls, aceasta este în stopRESPIRATOR, mai este cunoscut sub denumirea de asfixie. Dacă victima nu respiră și nu are puls, aceasta este în stopCARDIO-RESPIRATOR. Dacă această disfuncție, fie cardiacă, fie respiratorie nu este remediată rapid, poate conduce la decesul victimei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0384.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0384.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 384; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 383 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-cazul-unui-accidentat-care-nu-respira-pulsul-este-verificat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"383","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0385","batch":"08","category":"Categoria B","question":"Ce semnificație are indicatorul din imagine?","answers":["Trecere cu bacul peste o apă","Drum denivelat","Accesul interzis vehiculelor care transportă substanțe de natură să polueze apele"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul se numește “Accesul interzis vehiculelor care transportă substanțe de natură să polueze apele”, acesta interzice accesul tuturor vehiculelor care transportă substanțe de natură să polueze apele. Se întâlnește de obicei în zonele intens populate sau în zonele unde prezența unor astfel de substanțe ar constitui un pericol.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0385.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0385.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 385; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul interzice accesul vehiculelor care transportă substanțe periculoase. Șoferii care conduc astfel de vehicule trebuie să aleagă un alt traseu. Este important ca ceilalți participanți la trafic să fie atenți la condițiile drumului și să respecte regulile generale de circulație.","needsImageReview":true,"source":"RoDrive · ID 384 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-indicatorul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"384","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_395.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0386","batch":"08","category":"Categoria B","question":"Ce obligații aveți în situația prezentată?","answers":["Să limitați viteza de circulație în funcție de categoria autovehiculului pe care îl conduceți","Să limitați viteza de circulație în funcție de categoria drumului pe care vă deplasați","Indicatorul se adresează doar camioanelor de mare tonaj"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul pe care l-ați întâlnit se numește „Limitare de viteză diferențiată pe categorii de autovehicule”. Acest indicator obligă la limitarea vitezei pe categorii de autovehicule astfel: În cazul în care întâlniți acest indicator veți respecta limitarea impusă de acesta, indiferent de categoria drumului pe care vă deplasați. Prin urmare, în situația dată, conducând un autovehicul din categoria B, aveți obligația de a circula cu o viteză care să nu depășească 50 km/h.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0386.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0386.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 386; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator circular cu margini roșii, în interiorul căruia se află un camion în dreptul căruia scrie 30 și o mașină în dreptul căreia scrie 50. Indicatorul arată limitele de viteză aplicabile: 50 km/h pentru autoturisme și 30 km/h pentru camioane.","needsImageReview":true,"source":"RoDrive · ID 385 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"385","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_396.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0387","batch":"08","category":"Categoria B","question":"Unde opriți în situația prezentată?","answers":["În locul cu vizibilitate maximă, fără a depăși indicatorul","La cel puțin 5 m","La cel puțin 10 m"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Trecere la nivel cu o cale ferată dublă, fără bariere” însoțit de indicatorul „Oprire”. Aceste indicatoare vă avertizează că vă apropiați de o trecere la nivel cu o cale ferată dublă, fără bariere, unde aveți obligația de a opri în locul cu vizibilitate maximă, dar fără a depăși locul unde se află instalate indicatoarele, pentru a vă asigura că nu se apropie niciun vehicul feroviar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0387.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0387.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 387; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată cu indicatorul octogonal roșu pe care scrie 'STOP' și indicatorul alb cu margini roșii 'Crucea Sfântului Andrei'.","needsImageReview":true,"source":"RoDrive · ID 386 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/unde-opriti-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"386","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_397.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0388","batch":"08","category":"Categoria B","question":"Ați executat corect oprirea în această situație?","answers":["Da, pentru că autobuzul nu se află în acest moment în stație","Nu, pentru că acest spațiu este rezervat doar opririi autobuzului","Da, dacă semnalizați acest lucru cu lumina galbenă intermitentă"],"correctIndices":[1],"correct":1,"explanation":"Oprirea voluntară a vehiculelor este interzisă în stațiile mijloacelor de transport public de persoane, precum și la mai puțin de 25 de metri înainte și după acestea. Deci în situația dată ați oprit neregulamentar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0388.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0388.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 388; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o bandă dedicată pentru autobuze, semnalizată cu marcajul 'BUS'. Șoferul din imagine este oprit pe această bandă.","needsImageReview":true,"source":"RoDrive · ID 387 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ati-executat-corect-oprirea-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"387","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_398.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0389","batch":"08","category":"Categoria B","question":"Este interzisă staționarea unui autoturism în zona marcajului longitudinal continuu?","answers":["Nu","Da, în cazul în care conducătorii celorlalte vehicule ar fi determinaţi să treacă peste marcajul respectiv","Legal, nu este prevăzut"],"correctIndices":[1],"correct":1,"explanation":"Se interzice staționarea voluntară a vehiculelor în toate cazurile în care se interzice oprirea voluntară, iar oprirea voluntară se interzice în dreptul marcajului continuu, atunci când conducătorii celorlalte vehicule care circulă în același sens sunt obligați din această cauză să treacă peste acest marcaj, deoarece îi obligați pe ceilalți conducători de vehicule să efectueze o manevră interzisă pe acel sector de drum. Însă în situația în care prin staționare NU îi obligă pe conducătorii celorlalte vehicule care circulă în același sens să încalce marcajul continuu de separare a sensurilor de circulație,manevra de staționare este regulamentară, ca de exemplu pe un drum foarte lat sau pe un drum cu două sau mai multe benzi de circulație pe sens, unde, prin manevra de staționare, ceilalți conducători de vehicule nu sunt obligați din această cauză sa încalce marcajul continuu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0389.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0389.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 389; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 388 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-interzisa-stationarea-unui-autoturism-in-zona-marcajului-longitudinal-continuu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"388","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0390","batch":"08","category":"Categoria B","question":"Cum procedați corect dacă circulați înainte și semaforul indică lumină galbenă intermitentă?","answers":["Opriți, deoarece la următoarea comutare va apărea lumina roșie","Reduceți viteza, iar dacă se impune, acordați prioritate","Opriți întotdeauna"],"correctIndices":[1],"correct":1,"explanation":"Semnalul de culoare galbenă intermitent permite trecerea, însă conducătorul de vehicul este obligat să circule cu viteză redusă și să respecte semnificația semnalizării rutiere și a regulilor de circulație aplicabile în acel loc. Deci în situația dată aveți obligația de a circula cu viteză redusă și de a aplica regula priorității de dreapta deoarece intersecția devine una în carecirculația este nedirijată.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0390.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0390.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 390; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată din perspectiva unui șofer, iar semaforul din dreptul său are lumină galbenă intermitentă. Din dreapta și din stânga intersecției vin vehicule.","needsImageReview":true,"source":"RoDrive · ID 389 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-corect-daca-circulati-inainte-si-semaforul-indica-lumina-galbena-intermitenta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"389","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_400.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0391","batch":"08","category":"Categoria B","question":"Marcajul longitudinal continuu, aplicat pe axul drumului, permite încălcarea lui:","answers":["Numai de către conducătorii de motociclete și mopede","Numai de către vehiculele cu gabarit depășit","Nu, în nicio situație"],"correctIndices":[2],"correct":2,"explanation":"Marcajul longitudinal format dintr-o linie continuă simplă sau dublă interzice încălcarea acestuia. Semnificația acestui marcaj se respectă de către toți conducătorii de vehicule. Trebuie știut că în situația în care întâlniți marcajul format dintr-o linie continuă și una discontinuă, alăturate, trebuie să respectați semnificația liniei celei mai apropiate în sensul de mers. Dacă linia cea mai apropiată este cea discontinuă, trecerea peste acel marcaj este permisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0391.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0391.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 391; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 390 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/marcajul-longitudinal-continuu-aplicat-pe-axul-drumului-permite-incalcarea-lui","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"390","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0392","batch":"08","category":"Categoria B","question":"Ce obligații aveți la semnalul galben intermitent al semaforului electric?","answers":["Opriți, pentru că nu puteți intra în intersecție","Reduceți viteza și vă continuați deplasarea cu atenție, ocolind pietonii","Reduceți viteza și circulați respectând regulile aplicabile în acea intersecție"],"correctIndices":[2],"correct":2,"explanation":"Semnalul de culoare galbenă intermitent permite trecerea, însă conducătorul vehiculului este obligat să circule cu viteza redusă și să respecte semnificația semnalizării rutiere și a regulilor de circulație aplicabile în acel loc. De exemplu, dacă lângă semaforul care are în funcțiune semnalul de culoare galbenă intermitent se găsește instalat indicatorul de reglementare de prioritate “Cedează trecerea”, se va respecta semnificația indicatorului de reglementare de prioritate, fiind obligat să acordați prioritate de trecere. Acest semnal intermitent de culoare galbenă se poate întâlni și în zona trecerilor pentru pietoni, acesta este format dintr-un singur corp de iluminat și poate avea aplicată imaginea unui pieton. Acest semnal vă avertizează despre prezența unei treceri pentru pietoni, caz în care veți reduce viteza de deplasare și veți acorda prioritate de trecere pietonilor care traversează regulamentar sau care intenționează să traverseze pe trecerea pentru pietoni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0392.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0392.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 392; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 391 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-semnalul-galben-intermitent-al-semaforului-electric","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"391","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0393","batch":"08","category":"Categoria B","question":"Pentru care dintre faptele de mai jos se aplică sancțiuni contravenționale?","answers":["Conducerea pe drumurile publice a unui autovehicul / tractor agricol sau forestier sub influența băuturilor alcoolice, dacă fapta nu constituie, potrivit legii, infracțiune","Punerea în circulație sau conducerea pe drumurile publice a unui autovehicul neînmatriculat","Conducerea pe drumurile publice a unui autovehicul de către o persoană fără permis de conducere"],"correctIndices":[0],"correct":0,"explanation":"Conducerea pe drumurile publicea unui vehicul pentru care legea prevede obligativitatea deținerii permisului de conducerede către o persoană care are o îmbibație alcoolicădepeste 0,80 g/lalcool pur în sângeconstituieinfracțiuneși se pedepsește penal, cu închisoare de la unu la 5 ani sau cu amendă. În schimb, în cazul unei îmbibațiimai mici sau egale cusub 0,8 g/lalcool pur în sânge, aceasta constituiecontravențieși se sancționează cu amenda prevăzută în clasa a-IV-a de sancțiuni și cu suspendarea exercitării dreptului de a conduce pentru o perioada de 90 de zile. Trebuie să reținem că o concentrațiemai mică sau egală cu0,8 g/lalcool pur însângeconstituiecontravențieși se sancționează contravențional. Iar o concentrațiemai mare de0,8 g/lalcool pur însângeconstituieinfracțiunesi se pedepsește penal. Punerea în circulație sau conducerea pe drumurile publice a unui autovehicul, a unui tramvai sau a unui tractor agricol ori forestier neînmatriculat sau neînregistrat constituieinfracțiuneși se sancționează penal, cu închisoare de la unu la 3 ani sau cu amendă. Conducerea pe drumurile publice a unui autovehicul, a unui tramvai ori a unui tractor agricol sau forestier de către o persoană care nu posedă permis de conducere constituieinfracțiuneși se sancționează penal, cu închisoarea de la unu la 5 ani.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0393.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0393.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 393; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 392 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-care-dintre-faptele-de-mai-jos-se-aplica-sanctiuni-contraventionale","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"392","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0394","batch":"08","category":"Categoria B","question":"Pentru a circula pe un drum cu polei, se recomandă să echipați autoturismul cu:","answers":["Lanțuri pentru zăpadă","Pneuri speciale sau lanțuri antiderapante","Lopată și nisip"],"correctIndices":[1],"correct":1,"explanation":"Pentru autoturisme (autovehicule cu masa totală maximă autorizatăde până la 3,5 tone) este obligatorie doar dotarea cu anvelope de iarnă, pe drumurile publice acoperite cu zăpadă, gheață sau polei. Pentru acestea nu este obligatorie dotarea cu lanțuri sau alte echipamente antiderapante certificate. Dar pentru o aderență mult mai bună pe drumurile cu polei, se recomandă și utilizarea lanțurilor antiderapante. Trebuie să reținem că legislația rutieră obligă la dotarea cu anvelope de iarnădoar dacă drumurile publice sunt acoperite cu zăpadă, gheață sau polei. Această obligație nu o aveți în funcție de o dată calendaristică sau de un anotimp, obligația o aveți doar dacă drumurile publice sunt acoperite cu zăpadă, gheață sau polei. Trebuie știut că pentru autovehiculele cu o masă totală maximă autorizatămai mare de 3,5 toneși autovehiculul de transport persoane cu mai mult de 9 locuri pe scaune, inclusiv cel al conducătorului auto, este obligatorie dotarea cu anvelope de iarnă pe roțile axei/axelor de tracțiune sau, în lipsa anvelopelor de iarnă, lanțuri ori alte echipamente antiderapante certificate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0394.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0394.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 394; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum acoperit cu zăpadă în condiții de trafic intens.","needsImageReview":true,"source":"RoDrive · ID 393 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-a-circula-pe-un-drum-cu-polei-se-recomanda-sa-echipati-autoturismul-cu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"393","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_404.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0395","batch":"08","category":"Categoria B","question":"Precizați în care dintre situațiile de mai jos este interzisă depășirea:","answers":["La coborârile a căror pantă depășește 10%","Pe trecerile pentru pietoni sau pe cele la nivel cu calea ferată curentă și la mai puțin de 50 m de acestea","În situația în care, din sens opus, un vehicul este nevoit să execute o manevră, pentru a evita coliziunea"],"correctIndices":[1,2],"correct":1,"explanation":"Legislația rutieră nu prevede nimic în acest sens. Legislația rutieră interzice manevra de depășire a vehiculelor:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0395.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0395.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 395; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 394 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-in-care-dintre-situatiile-de-mai-jos-este-interzisa-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"394","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0396","batch":"08","category":"Categoria B","question":"În fața dvs. s-a produs un accident rutier care este cercetat de poliție, iar circulația se desfășoară anevoios, pe un singur sens. Cum veți proceda?","answers":["Vă continuați drumul cu atenție, respectând indicațiile polițistului rutier","Vă continuați drumul cu viteză sporită, pentru a nu bloca traficul rutier","Reduceți viteza și opriți în locul accidentului, pentru a vedea ce s-a întâmplat"],"correctIndices":[0],"correct":0,"explanation":"În situația în care circulați în zona producerii unui accident cercetat de politie, trebuie să vă continuați deplasarea cu atenție, respectând indicațiile polițistului rutier. Trebuie știut că în cazul în care întâlniți indicatorul „Accident” aveți obligația de a circula cu maxim 30 km/h în localități sau 50 km/h în afara localităților. În astfel de situații trebuie să circulați cu atenție și viteză redusă, nicidecum cu viteză sporită. Viteza va fi sporită doar la semnalul polițistului rutier care cercetează accidentul, prin rotirea vioaie a brațului. Nu se recomandă oprirea la locul accidentului, pentru a vedea ce s-a întâmplat, atat timp cât poliția este deja la locul accidentului, astfel se evită aglomerarea și mai mare a zonei. Dar trebuie știut că orice persoană care are cunoștință despre un accident de circulație în urma căruia a fost vătămată una sau mai multe persoane, are obligația de a anunța poliția și de a suna la numarul unic de urgență 112.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0396.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0396.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 396; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 395 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-fata-dvs-s-a-produs-un-accident-rutier-care-este-cercetat-de-politie-iar-circulatia-se-desfasoara-anevoios-pe-un-singur-sens-cum-veti-pro","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"395","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0397","batch":"08","category":"Categoria B","question":"Trebuie respectată semnificația unui indicator instalat pe partea stângă a drumului, orientat către conducătorii de vehicule care se apropie?","answers":["Nu, deoarece se adresează circulației din sens invers","Da, dar numai de către cei care circulă pe banda cea mai apropiată de axul drumului","Da, de către toți conducătorii de vehicule care îl întâlnesc"],"correctIndices":[2],"correct":2,"explanation":"Indicatoarele rutiere se instalează, de regulă, pe partea dreaptă a sensului de mers. Dacă se consideră că acestea nu pot fi observate, se pot instala ori repeta pe partea stânga, în zona mediană a drumului, pe un refugiu ori spatiu interzis circulației vehiculelor, deasupra părții carosabile sau de cealaltă parte a intersecției, în locuri vizibile pentru toți participanții la trafic. Semnificația unui indicator, indiferent de partea pe care este amplasat, este valabilă pe întreaga lățime a parții carosabile deschise circulației conducătorilor cărora li se adresează. Iar când indicatorul este instalat deasupra benzii sau benzilor, semnificația lui este valabilă numai pentru banda ori benzile astfel semnalizate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0397.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0397.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 397; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 396 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/trebuie-respectata-semnificatia-unui-indicator-instalat-pe-partea-stanga-a-drumului-orientat-catre-conducatorii-de-vehicule-care-se-apropie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"396","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0398","batch":"08","category":"Categoria B","question":"Purtarea centurii de siguranță este obligatorie în timpul circulației pe drumurile din localități?","answers":["Nu","Da, numai de către conducătorul autovehiculului","Da, de către cel de la volan şi de către pasagerii care ocupă locurile prevăzute cu asemenea dispozitive"],"correctIndices":[2],"correct":2,"explanation":"Conducătorii de autovehicule și tractoare agricole sau forestiere și persoanele care ocupă locuri prevăzute prin construcție cu centuri sau dispozitive de siguranță omologatetrebuie să le poarte în timpul circulației pe drumurile publice, indiferent dacă ocupă locurile din față sau din spate ale autovehiculului și indiferent dacă circulă în localitate sau în afara localității. Conducătorii de autovehicule având locuri prevăzute prin construcție cu centuri de siguranță trebuie să informeze pasagerii cu privire la obligația legală de a le purta în timpul circulației pe drumurile publice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0398.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0398.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 398; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 397 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/purtarea-centurii-de-siguranta-este-obligatorie-in-timpul-circulatiei-pe-drumurile-din-localitati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"397","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0399","batch":"08","category":"Categoria B","question":"Care autovehicule pot fi echipate cu lumini speciale de avertizare de culoare albastră?","answers":["Legea nu prevede","Orice autovehicul pentru care se obține aprobarea poliției rutiere","Vehiculele aparținând poliției, jandarmeriei și poliției de frontieră"],"correctIndices":[2],"correct":2,"explanation":"Semnalul special de avertizare cu lumină de culoare albastră, împreună cu semnalul sonor, obligă participanții la trafic să acorde prioritate de trecere. Printre vehiculele pe care pot fi montate astfel de lumini speciale de avertizare de culoare albastră se găsesc și vehiculele aparținând poliției, jandarmeriei și poliției de frontieră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0399.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0399.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 399; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 398 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-autovehicule-pot-fi-echipate-cu-lumini-speciale-de-avertizare-de-culoare-albastra","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"398","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0400","batch":"08","category":"Categoria B","question":"Semnele unei fracturi sunt:","answers":["Durere în zona afectată","Durere și poziție nefirească","Temperatură mărită și transpirație abundentă"],"correctIndices":[1],"correct":1,"explanation":"Fractura reprezintă ruptura unui os sau a unui cartilaj al unui membru al corpului. Cel mai frecvent, acestea apar la nivelul membrelor iar cei mai predispuși la producerea fracturilor sunt persoanele în vârstă, datorită elasticității mai mici a oaselor. Fracturile pot fi: Semne de recunoaștere: Primul ajutor în cazul unei fracturi:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0400.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0400.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 400; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 399 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnele-unei-fracturi-sunt","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"399","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
